<?php require_once 'includes/bootstrap.php'; if(current_user()) redirect('dashboard.php'); $errors=[]; $old=['full_name'=>'','email'=>'']; if($_SERVER['REQUEST_METHOD']==='POST'){ $old['full_name']=trim($_POST['full_name']??'');$old['email']=trim($_POST['email']??''); if(!verify_csrf())$errors[]='Security check failed. Please try again.'; if(strlen($old['full_name'])<2||strlen($old['full_name'])>100)$errors[]='Name must be between 2 and 100 characters.'; if(!validate_email($old['email']))$errors[]='Please enter a valid email address.'; $pass=$_POST['password']??'';$confirm=$_POST['confirm_password']??''; if(strlen($pass)<8||!preg_match('/[A-Z]/',$pass)||!preg_match('/[a-z]/',$pass)||!preg_match('/\d/',$pass))$errors[]='Password must be at least 8 characters and include upper, lower and a number.'; if($pass!==$confirm)$errors[]='Passwords do not match.'; if(!$errors){$s=db()->prepare('SELECT id FROM users WHERE email=?');$s->execute([$old['email']]);if($s->fetch())$errors[]='An account with this email already exists.';} if(!$errors){$hash=password_hash($pass,PASSWORD_DEFAULT);$s=db()->prepare('INSERT INTO users(full_name,email,password_hash,role) VALUES(?,?,?,?)');$s->execute([$old['full_name'],$old['email'],$hash,'normal']);flash('success','Registration successful. Please log in.');redirect('login.php');}} page_head('Register','Create a secure learner account on Learn with Nazmul.'); site_header('register.php'); ?>
<main><section class="narrow"><div class="form-card"><p class="section-label">JOIN THE PLATFORM</p><h1>Create your account</h1><p>Register to enrol in courses and access your learner dashboard.</p><?php if($errors): ?><div class="alert error" role="alert"><ul><?php foreach($errors as $x): ?><li><?= e($x) ?></li><?php endforeach; ?></ul></div><?php endif; ?><form method="post" novalidate><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><div class="form-group"><label for="full_name">Full name</label><input id="full_name" name="full_name" required minlength="2" maxlength="100" value="<?= e($old['full_name']) ?>" autocomplete="name"></div><div class="form-group"><label for="email">Email</label><input id="email" type="email" name="email" required maxlength="150" value="<?= e($old['email']) ?>" autocomplete="email"></div><div class="form-group"><label for="password">Password</label><input id="password" type="password" name="password" required minlength="8" autocomplete="new-password"><small>Use at least 8 characters with upper/lower case and a number.</small></div><div class="form-group"><label for="confirm_password">Confirm password</label><input id="confirm_password" type="password" name="confirm_password" required minlength="8" autocomplete="new-password"></div><button class="button primary-button" type="submit">Register</button></form><p class="form-note">Already registered? <a href="<?= e(url('login.php')) ?>">Log in</a>.</p></div></section></main><?php site_footer(); ?>